// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(address logAddr1, address logAddr2) public {
        vm.assume(logAddr1 != logAddr2);
        vm.assume(logAddr1 != address(0));
        vm.assume(logAddr2 != address(0));
        c.SetLogFile(logAddr1);
        c.Initialized();
        bool reverted;
        try c.SetLogFile(logAddr2) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted);
    }
}
